function teacherEditLink(){return `<section class="panel"><h3>교사용</h3><p class="tiny muted">문제 파일을 GitHub에서 직접 고칩니다. 저장 권한이 있는 교사 계정으로 로그인해야 저장할 수 있어요.</p><a class="btn blue full" style="display:block;text-align:center;text-decoration:none" href="${teacherEditUrl}" target="_blank" rel="noopener">📝 GitHub에서 문제 수정</a></section>`}
function readerForPostcard(key,fallback){const roster=[fallback,{name:'독자',face:'🧑🏻',portrait:'assets/story-characters/reader-01.png?v=reader-20261027-1',role:'학생 독자',readerCutout:true},{name:'독자',face:'👧🏻',portrait:'assets/story-characters/reader-02.png?v=reader-20261027-1',role:'학생 독자',readerCutout:true},{name:'독자',face:'🧑🏻',portrait:'assets/story-characters/reader-03.png?v=reader-20261027-1',role:'지역 독자',readerCutout:true},{name:'독자',face:'👵🏻',portrait:'assets/story-characters/reader-04.png?v=reader-20261027-1',role:'어르신 독자',readerCutout:true}],quizzes=game?.content?.quizzes||[],questionIndex=quizzes.findIndex(q=>q.after===Number(key.split(':')[1]));if(questionIndex<0)return fallback;const run=(game.history||[]).length,keyForRun=`today-paper-reader-order:${game.profile.class_name}:${game.profile.student_no}:${run}`;let assignment;try{assignment=JSON.parse(localStorage.getItem(keyForRun)||'null')}catch{}if(!Array.isArray(assignment)||assignment.length!==quizzes.length){assignment=shuffledIndices(quizzes.length).map(i=>Math.min(roster.length-1,Math.floor(i*roster.length/quizzes.length)));localStorage.setItem(keyForRun,JSON.stringify(assignment))}return roster[assignment[questionIndex]]||fallback}

function tone(freq=600,duration=.12,type='sine'){
  if(!soundOn)return;
  try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audio.currentTime);gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}
}
$('#sound').onclick=()=>{soundOn=!soundOn;localStorage.setItem('sound',soundOn?'on':'off');$('#sound').textContent=soundOn?'🔊':'🔇'};$('#sound').textContent=soundOn?'🔊':'🔇';
async function api(path,body){if(window.staticApi)return window.staticApi(path,body);const opts=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};const res=await fetch(new URL('api/'+path,location.href),opts),data=await res.json();if(!res.ok)throw Error(data.error||'요청에 실패했습니다.');return data}
function request(path,body={}){return api(path,{...body,request_id:requestId()})}
function showError(error,target=screen){let el=$('.error',target);if(!el){el=document.createElement('p');el.className='error';target.prepend(el)}el.textContent=error.message||String(error)}
function modal(html){overlayContent.innerHTML=html;overlayContent.classList.toggle('photo-preview-card',!!$('.photo-preview',overlayContent));overlayContent.classList.toggle('growth-card',!!$('.growth-celebration',overlayContent));overlayContent.classList.toggle('story-dialogue-card',!!$('.story-dialogue',overlayContent));overlay.classList.remove('hidden')}
