function flash(){const el=document.createElement('div');el.className='confetti';document.body.append(el);setTimeout(()=>el.remove(),2200);tone(740,.18,'triangle');setTimeout(()=>tone(930,.3,'triangle'),160)}
function office(levelNum){const n=Math.min(5,levelNum),names=['동네 신문사','인기 신문사','유명 언론사','전국구 언론사','전설의 미디어 제국'],images=game?.content?.settings?.office_images||adminData?.content?.settings?.office_images||[],src=images[n-1]||'';return `<div class="office ${src?'has-photo':''}" data-level="${n}" aria-label="레벨 ${n} ${names[n-1]} 사무실">${src?`<img class="office-photo" src="${esc(src)}" alt="레벨 ${n} 사무실">`:''}<div class="wall"></div><div class="floor"></div><div class="window"><div class="outside"></div></div><div class="lamp">💡</div><div class="sign">${n===5?'✨ 미디어 제국':esc(names[n-1])}</div><div class="board">${n<3?'마감 중…':'📈 실시간 속보<br>NEWS LIVE'}</div><div class="shelf">📚<br>📁</div><div class="newsroom">NEWS<br>STUDIO</div><div class="desk second-desk"></div><div class="desk"></div><div class="editor">🧑🏻‍💻</div><div class="computer">🖥️</div><div class="staff">👩🏽‍💼</div><div class="staff2">🧑🏽‍💼</div><div class="plant">🪴</div><div class="camera">🎥</div><div class="trophy">🏆</div><div class="spark">✨</div></div>`}
function levelName(n){return ['동네 신문사','인기 신문사','유명 언론사','전국구 언론사','전설의 미디어 제국'][n-1]}
function nextText(key){return key.startsWith('plan:')?(key==='plan:0'?'☎️ 취재 시작하기':'🗞️ 기사 기획 이어가기'):key.startsWith('verify:')?'🔎 팩트체크 미션 시작':key==='publish'?'📰 기사 발행하기':key==='complete'?'🏆 결과 보기':key.startsWith('boss:')?'⚔️ 보스전 계속하기':key.startsWith('quiz:')?'📬 독자 엽서 도착!':'📝 다음 기사 제작하기'}
