function renderWelcome(){screen.innerHTML=`<section class="panel hero"><span class="pill">🎮 6개의 기사 · 최종 팩트체크</span><h1>오늘신문<br>신입 편집장의 첫 번째 특종</h1><p>폐간 위기의 신문사를 맡아 특집 기사를 기획하고 발행하세요.<br>독자의 질문에 답하고 자료를 검증해 오늘신문을 지켜 주세요!</p>${office(1)}</section><section class="panel"><h2>신입 편집자 등록</h2><p class="muted">반과 번호를 선택하고 닉네임을 정하세요. 기록은 이 브라우저에 저장됩니다.</p><div class="row"><label class="field">반<select id="reg-class">${classes.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field">번호<select id="reg-no">${Array.from({length:37},(_,i)=>`<option value="${i+1}">${i+1}번</option>`).join('')}</select></label></div><label class="field">닉네임<input id="reg-nick" maxlength="20" placeholder="예: 멍멍일보"></label><button class="btn primary full" id="register">🚀 신문사 만들기</button><hr><h3>기존 기록 이어하기</h3><div class="row"><label class="field">반<select id="rec-class">${classes.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field">번호<select id="rec-no">${Array.from({length:37},(_,i)=>`<option value="${i+1}">${i+1}번</option>`).join('')}</select></label></div><label class="field">복구 코드<input id="rec-code" autocomplete="off" placeholder="발급받은 복구 코드"></label><button class="btn blue full" id="recover">↩️ 이어서 접속</button><p class="tiny muted">기기나 브라우저 데이터를 지우면 기록도 함께 삭제됩니다.</p></section>`;
 $('#register').onclick=async()=>{try{const d=await api('register',{class_name:$('#reg-class').value,student_no:+$('#reg-no').value,nickname:$('#reg-nick').value});game=d.game;modal(`<h2>🎉 신입 편집자 환영!</h2><p>당신은 오늘부터 신문사 편집자입니다. 정확하고 흥미로운 기사를 발행해 조회수 100만을 달성해 보세요!</p><p>이 코드는 같은 브라우저에서 기록을 다시 선택할 때 사용합니다.</p><div class="code">${esc(d.recovery_code)}</div><p class="tiny">기록은 이 브라우저에 저장됩니다. 브라우저 데이터를 지우면 기록과 코드도 사라집니다.</p><button class="btn primary full" id="start-go">게임 시작!</button>`);$('#start-go').onclick=()=>{closeModal();render()}}catch(e){showError(e)}};
 $('#recover').onclick=async()=>{try{const d=await api('recover',{class_name:$('#rec-class').value,student_no:+$('#rec-no').value,code:$('#rec-code').value});game=d.game;render()}catch(e){showError(e)}};
}
function unlockedPostcardCount(){const total=game?.content?.quizzes?.length||0,milestones=[0,0,0,3,6,8,10],sent=Math.min(6,game?.state?.published?.length||0);return Math.min(total,game?.unlocked_quizzes??milestones[sent])}
function openReaderInbox(returnKey=null){const questions=game.content.quizzes||[],unlocked=unlockedPostcardCount();if(!unlocked){modal(`<div class="reader-inbox"><h2>🔒 독자 엽서함</h2><p>기사 3편을 발행하면 첫 엽서 3장이 도착해요.</p><button class="btn primary full" id="inbox-home">🏠 메인 화면</button></div>`);$('#inbox-home').onclick=()=>{closeModal();render()};return}readerReturnKey=returnKey;const solved=game.state.solved||[],required=[3,3,3,4,4,4,5,5,6,6];modal(`<div class="reader-inbox"><div class="reader-inbox-head"><div><span class="pill">📬 열린 엽서 ${unlocked}/${questions.length}</span><h2>독자 엽서함</h2><p>기사를 발행할 때마다 새 엽서가 차례로 도착해요.</p></div><div class="inbox-head-actions"><button class="btn inbox-home" id="inbox-home">🏠 메인 화면</button><button class="btn" id="inbox-close">닫기</button></div></div><div class="inbox-list">${questions.map((q,i)=>{const key='quiz:'+q.after,done=solved.includes(key),locked=i>=unlocked;return `<button class="inbox-card ${done?'is-read':''} ${locked?'is-locked':''}" ${locked||done?'disabled':`data-inbox-open="${q.after}"`}><span class="inbox-stamp">${locked?'🔒':done?'✓':'✉'}</span><span><b>독자 엽서 ${String(i+1).padStart(2,'0')}</b><small>${locked?`기사 ${required[i]}편 발행 후 도착해요`:esc(q.prompt)}</small></span><strong>${locked?'잠김':done?'답변 완료':'열어보기 →'}</strong></button>`}).join('')}</div></div>`);$('#inbox-home').onclick=()=>{readerReturnKey=null;closeModal();render()};$('#inbox-close').onclick=()=>{readerReturnKey=null;closeModal()};overlayContent.querySelectorAll('[data-inbox-open]').forEach(b=>b.onclick=()=>openReaderPostcard(Number(b.dataset.inboxOpen)))}
function openReaderPostcard(n=101){const number=(game.content.quizzes||[]).findIndex(q=>q.after===n)+1;if(number<1||number>unlockedPostcardCount())return openReaderInbox(readerReturnKey);modal(`<div class="postcard-arrival"><div class="mail-cancel"><span class="pill">📬 새 우편 도착</span><button class="btn" id="mail-close">엽서함으로</button></div><div class="postcard-envelope" id="postcard-envelope"><div class="envelope-flap"></div><div class="envelope-letter">📝</div><div class="envelope-stamp">우표<br>NEWS</div><b>편집장님께</b><p>독자의 질문 ${number}번이 도착했어요.</p><small>보낸 사람 · 오늘신문을 읽은 독자</small></div><button class="btn primary full" id="postcard-open">엽서 펼쳐보기</button></div>`);$('#mail-close').onclick=()=>openReaderInbox(readerReturnKey);$('#postcard-open').onclick=()=>{const btn=$('#postcard-open');btn.disabled=true;$('#postcard-envelope').classList.add('opened');tone(520,.12,'triangle');setTimeout(()=>{closeModal();renderQuestion('quiz:'+n)},650)}}
function renderGame(){const s=game.state,c=game.content.settings,n=game.level,threshold=c.thresholds[n],remaining=n===5?0:Math.max(0,threshold-s.views),range=n===5?1:threshold-c.thresholds[n-1],progress=n===5?100:Math.max(0,100-(remaining/range*100)),pending=Math.max(0,s.article-(s.published?.length||0)),unlocked=unlockedPostcardCount(),unread=game.content.quizzes.slice(0,unlocked).filter(q=>!(s.solved||[]).includes('quiz:'+q.after)).length,canCreate=game.next.startsWith('article:');
 screen.innerHTML=`<section class="game-home"><div class="game-home-head"><div><span class="pill">LEVEL ${n===5?'MAX':n} · ${esc(levelName(n))}</span><strong>${esc(game.profile.nickname)}의 신문사</strong></div><div class="head-tools"><span class="mission-badge">📰 ${s.article}/6</span><button class="btn record-mini" id="record">📋 기록</button><button class="btn restart-mini" id="restart-game">↻ 다시 시작</button></div></div><button class="office-stage" id="office-inspect" aria-label="사무실 확대해서 보기">${office(n)}<div class="office-hud"><div class="hud-views"><small>누적 조회수</small><b id="view-number">${fmt(s.views)}</b></div><div class="hud-level"><span>${n===5?'성장 완료':`다음 레벨까지 ${fmt(remaining)}`}</span><div class="progress"><i style="width:${progress}%"></i></div><div class="reader-interest-chip">💬 독자 관심도 보너스 +${(s.reader_interest||0)*10}%</div></div></div></button><div class="game-actions"><div class="action-pair"><button class="btn create-action" id="create-article" ${canCreate?'':'disabled'}><span>📝 기사 제작하기</span><small>${canCreate?'다음 기사 미션':'현재 미션을 마치면 가능'}</small></button><button class="btn publish-action" id="publish-articles" ${pending?'':'disabled'}><span>📰 기사 발행하기</span><small>${pending}/6 발행 대기</small></button></div><button class="btn blue full" id="next" ${canCreate||game.next==='publish'?'hidden':''}>${nextText(game.next)}</button><button class="btn postcard-count-btn full ${unread?'has-unread':''}" id="reader-inbox" ${unlocked?'':'disabled'} aria-label="읽지 않은 엽서 ${unread}/${unlocked||game.content.quizzes.length}"><span>${unlocked?'📬 읽지 않은 엽서':'🔒 기사 3편 발행 후 열려요'}</span><b>${unread}/${unlocked||game.content.quizzes.length}</b></button><button class="btn help-mini" id="help">❔ 안내</button></div></section><a class="teacher-compact" href="${teacherEditUrl}" target="_blank" rel="noopener">교사용 문제 수정 ↗</a>`;
 $('#next').onclick=()=>{if(game.next==='complete')renderResult();else if(game.next==='publish')publish();else if(game.next.startsWith('quiz:'))openReaderPostcard();else renderQuestion()};$('#create-article').onclick=()=>{if(canCreate)renderQuestion()};$('#publish-articles').onclick=()=>{if(pending)publish()};$('#record').onclick=renderRecord;$('#reader-inbox').onclick=()=>{if(unlocked)openReaderInbox()};$('#restart-game').onclick=confirmRestart;$('#office-inspect').onclick=()=>{modal(`<div class="office-inspect-modal"><div class="inspect-modal-head"><span class="pill">LEVEL ${n===5?'MAX':n}</span><button class="btn inspect-close" id="inspect-close" aria-label="닫기">✕</button></div><h2>${esc(levelName(n))}</h2>${office(n)}<p>${['낡은 동네 신문사에서 첫 기사를 준비해요.','아담하고 깔끔한 인기 신문사로 성장했어요.','직원과 대형 모니터가 있는 유명 언론사예요.','고층 빌딩의 고급 뉴스 스튜디오예요.','황금 장식과 트로피가 빛나는 미디어 제국이에요.'][n-1]}</p><button class="btn primary full" id="inspect-done">사무실로 돌아가기</button></div>`);$('#inspect-close').onclick=closeModal;$('#inspect-done').onclick=closeModal};$('#help').onclick=()=>modal(`<h2>게임 안내</h2><p>기사 6개에서 자료 선택과 효과 판단 문제를 풀고 발행하세요. 3번째 기사 발행 때 엽서 3장, 4번째에 3장, 5번째에 2장, 6번째에 2장이 도착해요. 여섯 기사를 마치면 조회수와 관계없이 보스전에 도전할 수 있어요.</p><p>조회수는 신문사를 성장시키는 게임 수치입니다. 학습 점수는 첫 시도의 정답 여부로만 결정됩니다.</p><button class="btn primary" onclick="closeModal()">확인</button>`)
}
function questionData(key){const b=key.split(':');if(b[0]==='article')return game.content.articles[+b[1]][b[2]];if(b[0]==='quiz')return game.content.quizzes.find(x=>x.after===+b[1]);if(b[0]==='plan')return game.content.planning[+b[1]];if(b[0]==='verify')return game.content.verification[+b[1]];return game.content.boss[+b[1]]}
function mediaArt(choice){if(choice.image)return `<img src="${esc(choice.image)}" alt="자료 보기 이미지">`;const kind=choice.kind;
 if(kind==='graph'||kind==='infographic'){let nums=(choice.title.match(/\d[\d,]*/g)||[]).map(x=>Number(x.replace(/,/g,'')));if(nums.length>4&&nums.length%2===0)nums=nums.filter((_,i)=>i%2===1);const values=nums.length>=2?nums.slice(-4):[35,56,78,91],max=Math.max(...values);return `<div class="mini-chart" aria-label="자료 수치 그래프">${values.map((n,i)=>`<span title="${n}" style="height:${Math.max(10,Math.round(n/max*88))}%;background:${['#83bde8','#89d7c5','#efaa80','#c3afe6'][i%4]}">${n}</span>`).join('')}</div>`}
 if(kind==='table'){const found=[...choice.title.matchAll(/([가-힣 ]+)\s+(\d[\d,]*)/g)].slice(0,3);return `<div class="mini-table" aria-label="자료 표"><b>구분</b><b>수치</b>${(found.length?found.map(m=>[m[1].trim(),m[2]]):[['항목 A','—'],['항목 B','—'],['항목 C','—']]).map(([a,b])=>`<span>${esc(a)}</span><span>${esc(b)}</span>`).join('')}</div>`}
 if(kind==='map')return `<div class="mini-map" aria-label="예시 지도"><i></i><em>📍</em><strong>🏫</strong></div>`;
 const subject=/급식|메뉴/.test(choice.title)?'🍽️':/휴대전화|스마트폰|앱/.test(choice.title)?'📱':/자전거|헬멧/.test(choice.title)?'🚲':/하늘|먼지/.test(choice.title)?'☁️':/책/.test(choice.title)?'📚':/텀블러|컵/.test(choice.title)?'🥤':'🌿';return `<div class="mini-scene ${kind==='photo'?'photo':'drawing'}"><span>${subject}</span><small>${esc(choice.title)}</small></div>`}
function storyFor(key){
 const p=key.split(':'),kind=p[0],i=Number(p[1]);
 const owner={name:'신문사 사장',face:'🧑🏻‍💼',portrait:'assets/story-characters/owner.png?v=fade-20261027-6',role:'신문사 사장'},reporter={name:'취재 기자',face:'🧑🏻‍💻',portrait:'assets/story-characters/reporter.png?v=fade-20261027-6',role:'취재 기자'},designer={name:'디자인 팀장',face:'👩🏻‍🎨',portrait:'assets/story-characters/designer.png?v=fade-20261027-6',role:'디자인 팀장'},fact={name:'팩트체크 팀장',face:'🕵🏻‍♀️',portrait:'assets/story-characters/fact-checker.png?v=fade-20261027-6',role:'팩트체크 팀장'},reader={name:'독자',face:'👩🏻',portrait:'assets/story-characters/reader.png?v=fade-20261027-6',role:'오늘신문 독자'};
 if(kind==='plan'&&i===0)return [[owner,'드디어 왔군! 우리 신문사의 새로운 편집장!'],[owner,'사실 우리 신문사는 지금 폐간 직전이야. 독자들이 우리 신문을 읽지 않거든…….'],[owner,'하지만 자네가 좋은 기사를 만들어 준다면 다시 유명한 신문사가 될 수 있을 거야!'],[reporter,'사장님! 긴급 제보입니다!'],[reporter,'겨울철 노로바이러스 식중독이 문제래요! 사람들이 겨울에는 음식이 잘 상하지 않는다고 방심하고 있대요!'],[owner,'좋아! 이번 특집 기사로 독자들의 관심을 되찾자!']];
 if(kind==='plan'&&i===1)return [[reporter,'좋아요. 겨울철 노로바이러스 식중독을 다루기로 했어요. 이번 기사를 읽은 독자들이 무엇을 알게 되면 좋을까요?'],[designer,'독자를 겁주는 데서 끝나지 않고, 정확한 위험 정보와 예방법을 알려 주면 도움이 되겠어요.']];
 if(kind==='plan'&&i===2)return [[reporter,'기사의 목적이 정해졌어요. 독자가 내용을 쉽게 따라오도록 어떤 순서로 전하면 좋을까요?'],[designer,'먼저 유행과 위험을 알리고, 감염 경로와 증상을 설명한 뒤 예방법으로 이어가면 이해하기 쉬워요.']];
 if(kind==='plan'&&i===3)return [[owner,'좋아, 기사의 흐름이 잡혔군. 이제 독자의 눈길을 끌면서도 내용을 정확히 나타내는 제목을 골라 보게!'],[reporter,'과장된 표현은 피하고, 이번 특집의 핵심이 보이는 제목이면 좋겠어요.']];
 if(kind==='article'&&p[2]==='select'&&i===0)return [[reporter,'좋아요! 기사 기획이 끝났어요. 이제 제가 취재한 내용에 어울리는 자료를 찾아 주세요!'],[designer,'글만으로는 독자가 이해하기 어려울 수도 있겠네요. 어떤 자료를 넣으면 좋을까요?']];
 if(kind==='article'&&p[2]==='select')return [[reporter,`좋아요, ${i+1}번째 취재 내용도 정리됐어요.`],[designer,'이번에도 본문에 꼭 필요한 자료를 찾아봅시다.']];
 if(kind==='article'&&p[2]==='effect')return [[designer,'이 자료를 넣으면 독자들이 어떤 점을 더 쉽게 이해할 수 있을까요?'],[reporter,'기사 내용과 자료가 잘 맞는지도 생각해 봐요.']];
 if(kind==='quiz')return [[reporter,'전화벨이 울려요! 편집장님, 방금 기사를 읽은 독자에게서 질문이 도착했어요.'],[readerForPostcard(key,reader),'신문을 읽다가 궁금한 점이 생겼어요. 질문에 답해 주실 수 있나요?']];
 if(kind==='boss'&&i===0)return [[owner,'큰일이야! 악덕 편집장이 부정확한 자료를 퍼뜨리고 있어!'],[reporter,'우리가 만든 기사와 자료를 지켜야 해요. 편집장님, 준비됐죠?']];
 if(kind==='boss')return [[fact,`검증 ${i+1}단계입니다. 자료를 꼼꼼히 살펴 잘못된 주장을 막아 주세요.`],[owner,'좋아, 한 단계씩 해내고 있어! 끝까지 확인하세.']];
 if(kind==='verify'&&i===0)return [[reporter,'편집장님! 기사에 사용한 자료가 부적절하다는 제보예요!'],[owner,'신문사의 신뢰가 걸렸네. 사실인지 직접 확인해야 해.'],[fact,'먼저 자료가 기사 내용을 실제로 뒷받침하는지 검증하겠습니다.']];
 if(kind==='verify')return [[fact,i===1?'출처와 조사 시기를 확인해 자료의 신뢰성을 판단하세요.':i===2?'독자가 정보를 이해하는 데 알맞은 표현인지 살펴보세요.':'마지막입니다. 타당성, 신뢰성, 표현의 적절성을 함께 확인합시다.'],[reporter,'편집장님의 판단을 기다리고 있어요.']];
 return null;
}
function showStoryScene(key){
 const lines=storyFor(key);if(!lines?.length)return;if(key.startsWith('quiz:')){tone(920,.13,'square');setTimeout(()=>tone(760,.17,'square'),180)}
 const run=(game.history||[]).length,seenKey=`today-paper-story-v2:${game.profile.class_name}:${game.profile.student_no}:${run}:${key}`;
 if(localStorage.getItem(seenKey)==='1')return;
 let step=0;const officeImage=game.content.settings.office_images?.[game.level-1]||'';
 const finish=()=>{localStorage.setItem(seenKey,'1');closeModal()};
 const draw=()=>{const [speaker,text]=lines[step];modal(`<div class="story-dialogue" style="--story-office:url('${esc(officeImage)}')"><div class="story-scene-top"><span>${key==='plan:0'?'MISSION 01 · 겨울철 식중독의 진실을 알려라!':`오늘신문 · ${kindLabel(key)}`}</span><span>${step+1} / ${lines.length}</span></div><div class="story-backdrop">${officeImage?`<img class="story-scene-image" src="${esc(officeImage)}" alt="">`:``}<div class="story-light"></div><div class="story-portrait ${speaker.portrait?'has-portrait':''} ${speaker.readerCutout?'reader-cutout':''}" role="img" aria-label="${esc(speaker.role)} 초상화">${speaker.portrait?`<img src="${esc(speaker.portrait)}" alt="${esc(speaker.role)}">`:`<span>${speaker.face}</span>`}<small>${esc(speaker.role)}</small></div><div class="story-scene-caption">${esc(levelName(game.level))} · 편집부</div></div><div class="story-textbox"><div class="story-nameplate">${esc(speaker.name)}</div><p class="story-line" key="${step}">${esc(text)}</p><div class="story-controls"><button class="story-skip" id="story-skip">대화 건너뛰기</button><button class="btn primary story-next" id="story-next">${step===lines.length-1?'미션 시작':'다음 대사'} <span>▶</span></button></div></div></div>`);$('#story-next').onclick=()=>{if(step===lines.length-1)finish();else{step++;draw()}};$('#story-skip').onclick=finish};
 draw();
}
function kindLabel(key){const k=key.split(':')[0];return k==='plan'?'기사 기획':k==='article'?'기사 제작':k==='quiz'?'독자 엽서':k==='boss'?'최종 보스전':'최종 팩트체크'}
function renderQuestion(questionKey=game.next){const key=questionKey,q=questionData(key),parts=key.split(':'),isArticle=parts[0]==='article',isSelect=isArticle&&parts[2]==='select',isBoss=parts[0]==='boss',isQuiz=parts[0]==='quiz',isPlan=parts[0]==='plan',isVerify=parts[0]==='verify',isMulti=q.type==='multi',isOX=q.type==='ox',notice=transitionNotice,optionOrder=shuffledIndices(q.choices.length);selected=isMulti?[]:null;transitionNotice='';
 let intro='';if(isArticle){const a=game.content.articles[+parts[1]];intro=`<div class="pill">📰 기사 ${+parts[1]+1} / 6 · ${isSelect?'한 세트 · 1/2 자료 선택':'한 세트 · 2/2 효과 판단'}</div><h2>${esc(a.title)}</h2><div class="detail">${esc(a.body)}</div>${notice?`<p class="notice"><b>자료 선택 완료!</b><br>${esc(notice)}<br>이제 자료가 기사에 주는 효과를 판단해 보세요.</p>`:''}`}else if(isPlan){const titles=['기사 제재를 정해요','기사의 목적을 정해요','기사 내용의 순서를 정해요','기사 제목을 정해요'];intro=`<div class="pill">MISSION 01 · 기사 기획 ${+parts[1]+1}/4</div><h2 class="plan-stage-title">${titles[+parts[1]]}</h2>${+parts[1]<2?'<p class="reader-interest-tip">첫 시도에 정답을 고르면 이후 조회수 +10%</p>':''}` }else if(isVerify){const lines=['🚨 기자: 기사 자료가 부적절하다는 제보가 들어왔어요!','🕵️ 팩트체크 팀장: 출처와 조사 시기를 확인합시다.','🕵️ 팩트체크 팀장: 자료가 전달 목적에 알맞은지도 검토해야 합니다.','🕵️ 팩트체크 팀장: 마지막으로 세 기준을 함께 적용해 보세요.'];intro=`<div class="pill">최종 미션 · 팩트체크 ${+parts[1]+1}/4</div><p class="notice">${lines[+parts[1]]}</p>`}else if(isBoss){intro=`<div class="pill">⚔️ 최종 보스전 ${+parts[1]+1} / 3</div><div class="boss" id="boss-char">😈</div><div class="boss-hp"><i style="width:${100-[0,30,60][+parts[1]]}%"></i></div><p class="muted">악덕 편집장: “${esc(game.content.boss_dialogue||'조회수만 잘 나오면 되는 거 아니야?')}”</p>${q.image?`<div class="media-art enlarged"><img src="${esc(q.image)}" alt="보스전 문제 자료"></div>`:''}`}else intro=`<div class="reader-postcard-label"><span>📮 독자 엽서</span><b>독자 엽서 ${game.content.quizzes.findIndex(x=>x.after===Number(parts[1]))+1}번</b></div><p class="postcard-greeting">편집장님께, 기사 잘 읽었어요. 궁금한 점이 있어요!</p>`;
 const choices=isSelect?`<div class="media-grid">${optionOrder.map((choiceIndex,slot)=>{const c=q.choices[choiceIndex],label='ABCD'[slot];return `<button class="media" data-choice="${choiceIndex}"><div class="media-art">${mediaArt(c)}</div><h4>보기 ${label}</h4><span class="tiny">🔍 사진 확대</span></button>`}).join('')}</div>`:`<div class="${isOX?'ox-choices':isMulti?'multi-choices':''}">${optionOrder.map((choiceIndex,slot)=>{const c=q.choices[choiceIndex];return `<button class="choice" data-choice="${choiceIndex}"><span class="letter">${isOX?esc(c):'ABCD'[slot]}</span>${isOX?'':`<span>${esc(typeof c==='string'?c:c.title)}</span>`}</button>`}).join('')}</div>`;
 screen.innerHTML=`<section class="panel ${isQuiz?'reader-letter-panel':''}"><div class="question-toolbar"><span>📰 오늘신문 · ${kindLabel(key)}</span><div class="question-actions"><button class="btn mailbox-mini" id="reader-inbox-question">📬 엽서함 ${game.content.quizzes.filter(q=>!(game.state.solved||[]).includes('quiz:'+q.after)).length}</button><button class="btn restart-mini" id="restart-question">↻ 다시 시작</button></div></div>${intro}<div class="mission-card"><h2>${esc(q.prompt)}</h2>${choices}<p id="selection" class="muted tiny">${isSelect?'자료를 누르면 확대해서 볼 수 있습니다.':isMulti?'해당하는 답을 모두 선택하세요.':'정답이라고 생각하는 선택지를 눌러 주세요.'}</p><button class="btn primary full" id="submit" disabled>선택 제출하기</button></div></section>`;
 $('#restart-question').onclick=confirmRestart;$('#reader-inbox-question').onclick=()=>openReaderInbox(key);screen.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{const picked=+el.dataset.choice;if(isMulti)selected=selected.includes(picked)?selected.filter(i=>i!==picked):[...selected,picked];else selected=picked;screen.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',isMulti?selected.includes(+x.dataset.choice):+x.dataset.choice===selected));$('#submit').disabled=isMulti?selected.length===0:selected===null;if(isSelect){const c=q.choices[selected];$('#selection').textContent='사진을 확인한 뒤 선택 제출하기를 눌러 주세요.';modal(`<div class="photo-preview"><div class="row photo-preview-head"><strong>🔍 보기 ${'ABCD'[optionOrder.indexOf(selected)]} 사진</strong><button class="btn" id="photo-preview-close">닫기</button></div><div class="photo-preview-image-wrap"><img src="${esc(c.image)}" alt="선택한 보기 사진 전체"></div><button class="btn primary full" id="photo-preview-done">사진 확인하고 돌아가기</button></div>`);$('#photo-preview-close').onclick=closeModal;$('#photo-preview-done').onclick=closeModal}});
 $('#submit').onclick=async()=>{const button=$('#submit');button.disabled=true;try{const r=await request('answer',{key,choice:selected});game=r.game;if(r.correct&&!isPlan){const claim=await runViewGraph(key);game=claim.game;r.views_reward=claim.reward.views;r.applied_multiplier=claim.reward.applied_multiplier||1;r.level_from=claim.reward.level_from;r.level_to=claim.reward.level_to}tone(r.correct?800:240,.2,r.correct?'triangle':'sawtooth');const viewGain=r.correct?`<div class="small-view-reward">👀 조회수 +${fmt(r.views_reward||0)}${r.applied_multiplier>1?` · ${r.applied_multiplier}배 적용`:''}</div>${r.level_to>r.level_from?`<div class="growth-celebration-inline">🎉 신문사가 성장했습니다! LEVEL ${r.level_to===5?'MAX':r.level_to} · ${esc(levelName(r.level_to))}</div>`:''}`:'';if(isBoss&&r.correct){$('#boss-char')?.classList.add('hit');$('.boss-hp i').style.width=([70,40,0][+parts[1]])+'%';if(game.next==='complete')flash()}if(isSelect&&r.correct){transitionNotice=`${r.explanation} · 👀 조회수 +${fmt(r.views_reward||0)}${r.level_to>r.level_from?` · 🎉 신문사 LEVEL ${r.level_to===5?'MAX':r.level_to} 성장!`:''}`;modal(`<div class="view-claim-confirm"><span class="pill">📈 자료 선택 보상</span><h2>조회수가 기록됐어요!</h2><div class="big-number">+${fmt(r.views_reward||0)} 👀</div><p>현재 누적 조회수 <b>${fmt(game.state.views)}</b>회</p>${r.level_to>r.level_from?`<p class="growth-celebration-inline">🎉 신문사가 LEVEL ${r.level_to===5?'MAX':r.level_to}로 성장했어요!</p>`:''}<p>이제 선택한 자료가 기사에 주는 효과를 확인해요.</p><button class="btn primary full" id="effect-next">효과 문제로 이동</button></div>`);$('#effect-next').onclick=()=>{closeModal();if(r.level_to>r.level_from)flash();renderQuestion()};return}if(!r.correct&&isPlan){modal(`<div class="planning-feedback"><span class="pill">🗞️ 편집 회의</span><h2>한 번 더 생각해 봐요</h2><p>기사를 더 정확하고 읽기 쉽게 만들 선택을 찾아보세요.</p><p class="reader-hint">힌트: ${esc(r.hint||'제재와 기사 목적을 다시 살펴보세요.')}</p><button class="btn primary full" id="feedback-ok">다시 선택하기</button></div>`)}else if(!r.correct){const loss=r.view_penalty||0;modal(`<div class="reader-disappointment"><span class="reader-warning-tag">WARNING!</span><h2>📉 독자들의 실망!</h2><p>앗! 잘못된 답변에 독자들이 떠나가고 있어요.</p><div class="reader-loss"><small>조회수 하락</small><strong>${loss?`−${fmt(loss)}`:'0'} 👀</strong><p>${loss?'다시 답변해서 독자들의 마음을 되찾으세요!':'아직 줄일 조회수가 없어요.'}</p></div><p class="reader-hint">힌트: ${esc(r.hint||'다시 한 번 생각해 보세요.')}</p><button class="btn reader-retry full" id="feedback-ok">다시 답변하기</button></div>`)}else if(isPlan)modal(`<h2>⭕ 기획이 정리됐어요</h2><p class="notice">${esc(r.explanation)}</p>${viewGain}${r.interest_increased?`<div class="reader-reaction">💬 독자 관심도 상승! 이후 기사 조회수 +10%</div>`:''}<button class="btn primary full" id="feedback-ok">${game.next.startsWith('plan:')?'다음 기획 단계':'취재 자료 찾기'}</button>`);else if(isArticle&&!isSelect)modal(`<h2>📰 발행 준비 완료!</h2><p class="notice">${esc(r.explanation)}</p>${viewGain}<div class="story-response"><b>디자인 팀장</b><br>좋아요! 기사에 딱 맞는 자료예요. 발행 준비가 끝났습니다!</div><button class="btn primary full" id="feedback-ok">발행 화면으로</button>`);else if(isQuiz)modal(`<h2>⭕ 독자가 이해했어요!</h2><p class="notice">${esc(r.explanation)}</p>${viewGain}<div class="story-response"><b>독자</b><br>아하! 이제 이해했어요. 주변 사람들에게도 알려 줘야겠네요!</div><div class="story-response"><b>취재 기자</b><br>독자가 만족했어요! 우리 신문사의 인기가 올라갑니다!</div><button class="btn primary full" id="feedback-ok">엽서함으로 돌아가기</button>`);else modal(`<h2>⭕ 정답!</h2><p class="notice">${esc(r.explanation)}</p>${viewGain}<button class="btn primary full" id="feedback-ok">계속하기</button>`);$('#feedback-ok').onclick=()=>{closeModal();if(isPlan&&r.correct){renderQuestion();return}if(isBoss){if(game.next==='complete')renderResult();else renderQuestion()}else if(!r.correct&&isQuiz)renderQuestion(key);else if(isQuiz)openReaderInbox(readerReturnKey);else if(game.next==='complete')renderResult();else render()}}catch(e){button.disabled=false;showError(e)}}
 showStoryScene(key);
}
function animateViews(start,end){const el=$('#view-number');if(!el)return;const t=performance.now();function step(now){const p=Math.min(1,(now-t)/1300);el.textContent=fmt(Math.round(start+(end-start)*(1-(1-p)**3)));if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function animateRewardCounter(gain){const el=$('#reward-counter');if(!el||!gain)return;const t=performance.now();function step(now){const p=Math.min(1,(now-t)/1500),ease=1-(1-p)**4;el.textContent=`+${fmt(Math.round(gain*ease))} 👀`;if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function rewardModal(reward,title){const gain=reward.views||reward.prize?.type==='views'&&reward.prize.value||0,levelUp=reward.level_to>reward.level_from;
 if(levelUp)flash();if(gain>=100000)flash();
 const applied=Math.max(...(reward.applied_multipliers?.length?reward.applied_multipliers:[reward.applied_multiplier||1]));
 const reactions=['그래프가 있으니까 이해하기 쉬워요!','노로바이러스가 추위에 강하다니 몰랐어요!','사진과 그림 덕분에 내용을 쉽게 이해했어요!','생활에 도움이 되는 기사네요!','다음 기사도 기대할게요!'];
 const reaction=reward.type==='publish'?reactions[Math.floor(Math.random()*reactions.length)]:'';const employeeReaction=reward.type==='publish'?['편집장님, 독자들이 첫 기사를 읽기 시작했어요!','응원 편지가 쌓이고 있어요!','지역 독자들이 우리 기사를 공유하고 있어요!','전국에서 오늘신문 속보를 기다리고 있어요!','오늘신문이 최고의 미디어 제국으로 성장했어요!'][Math.max(0,(reward.level_to||game.level)-1)]:'';
 let message=`${reward.article_count||1}개 기사 발행 · 적용 배수 ${reward.applied_multipliers?.map(x=>`${x}배`).join(', ')||`${reward.applied_multiplier}배`}`;
 modal(`<div class="reward-modal-head"><h2>${esc(title)}</h2><button class="btn reward-exit" id="reward-exit">${reward.roulette_pending?'룰렛 열기 →':reward.postcards_unlocked?'엽서 보기 →':'계속 →'}</button></div><div class="newspaper">📰</div><p>${esc(message)}</p>${reaction?`<div class="reader-reaction ${applied>=10?'viral':''}">${esc(reaction)}</div>`:''}${employeeReaction?`<div class="story-response staff-response"><b>신문사 직원</b><br>${esc(employeeReaction)}</div>`:''}${reward.interest_percent?`<div class="reader-interest-reward">💬 독자 관심 보너스 +${reward.interest_percent}% 적용</div>`:''}<div class="big-number" id="reward-counter">${gain?`+${fmt(gain)} 👀`:'🎁 배수 보관!'}</div>${reward.postcards_unlocked?`<div class="new-postcards">📬 새 독자 엽서 ${reward.postcards_unlocked}장 도착!</div>`:''}${levelUp?`<div class="growth-celebration"><span class="growth-flash"></span><h2>🎉 신문사가 성장했습니다!</h2><p>LEVEL ${reward.level_to===5?'MAX':reward.level_to} · ${esc(levelName(reward.level_to))}</p><p>${['','새 책상과 햇살 드는 창문이 생겼어요.','깔끔한 편집실과 새 장식이 들어왔어요.','직원과 대형 뉴스 모니터가 함께해요.','고층 빌딩의 뉴스 스튜디오로 옮겼어요.','황금 트로피를 갖춘 미디어 제국이 됐어요.'][reward.level_to]}</p>${office(reward.level_to)}</div>`:''}<button class="btn primary full" id="reward-ok">${reward.roulette_pending?'🎡 룰렛 돌리기':reward.postcards_unlocked?'새 엽서 확인하기':levelUp?'새 사무실 둘러보기':'계속하기'}</button>`);if(gain)animateRewardCounter(gain);if(levelUp){tone(880,.3,'triangle');setTimeout(()=>tone(1100,.5,'triangle'),180)}const continueReward=()=>{closeModal();render();if(reward.postcards_unlocked&&!reward.roulette_pending){openReaderInbox();return}if(gain)animateViews(game.state.views-gain,game.state.views);if(levelUp){flash();$('.office',screen)?.classList.add('evolve')}};$('#reward-ok').onclick=continueReward;$('#reward-exit').onclick=continueReward;
}
function makeViewGraph(){let value=25000;return Array.from({length:101},(_,i)=>{value=Math.max(1,Math.min(50000,value+(Math.random()-.49)*26000+Math.sin(i*.47)*1800));return Math.round(value)})}
function viewGraphSvg(values,index,maxValue=50000){const x=i=>24+i*5.5,y=v=>205-v/maxValue*175,points=values.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' '),v=values[index],ticks=Array.from({length:6},(_,i)=>maxValue*i/5);return `<svg class="view-graph-svg" viewBox="0 0 600 235" role="img" aria-label="조회수 변동 그래프"><g class="view-graph-grid">${ticks.map(n=>`<line x1="24" x2="574" y1="${y(n)}" y2="${y(n)}"/><text x="2" y="${y(n)+4}">${n?`${n/10000}만`:'0'}</text>`).join('')}</g><path class="view-graph-line" d="${points}"/><circle class="view-graph-dot-halo" cx="${x(index)}" cy="${y(v)}" r="11"/><circle class="view-graph-dot" cx="${x(index)}" cy="${y(v)}" r="6"/></svg>`}
function runViewGraph(key){return new Promise(resolve=>{const multiplier=key.startsWith('boss:')?Math.max(1,game.state.pending_boss_multiplier||1):1,maxValue=50000*multiplier,values=makeViewGraph().map(v=>v*multiplier);let index=Math.floor(Math.random()*values.length),frame=0,stopped=false;modal(`<div class="view-game"><span class="pill">정답 보상 · 조회수 그래프</span><h2>멈춤을 눌러 조회수를 정하세요!</h2><p>빨간 점이 그래프를 따라 움직여요. 원하는 순간에 멈춰 보세요.</p><div class="view-graph-wrap"><div class="view-graph-current"><small>멈추면 받을 조회수${multiplier>1?` · ${multiplier}배 적용`:''}</small><b id="graph-value">${fmt(values[index])}</b></div><div id="view-graph">${viewGraphSvg(values,index,maxValue)}</div></div><div class="view-graph-scale"><span>0</span><span>${fmt(maxValue)}회</span></div><button class="btn primary full view-stop" id="graph-stop">⏹ 멈추고 조회수 받기</button></div>`);let previous=performance.now();function animate(now){if(stopped)return;if(now-previous>18){index=(index+1)%values.length;previous=now;$('#graph-value').textContent=fmt(values[index]);$('#view-graph').innerHTML=viewGraphSvg(values,index,maxValue)}frame=requestAnimationFrame(animate)}frame=requestAnimationFrame(animate);$('#graph-stop').onclick=async()=>{if(stopped)return;stopped=true;cancelAnimationFrame(frame);const button=$('#graph-stop');button.disabled=true;try{const result=await request('claim',{key,views:Math.round(values[index]/multiplier)});game=result.game;resolve(result)}catch(e){stopped=false;button.disabled=false;frame=requestAnimationFrame(animate);showError(e,overlayContent)}}})}
async function resumeViewGraph(){if(!game?.state.pending_view_claims?.length||!overlay.classList.contains('hidden'))return;try{const key=game.state.pending_view_claims[0],result=await runViewGraph(key);game=result.game;render()}catch(e){showError(e)}}
function confirmRestart(){modal('<div class="restart-confirm"><span class="pill">🔄 새 게임</span><h2>지금 다시 시작할까요?</h2><p>현재까지의 조회수와 학습 점수는 기록에 남고, 진행 중인 판은 중간 종료로 저장됩니다.</p><div class="row"><button class="btn" id="restart-cancel">계속하기</button><button class="btn pink" id="restart-confirm">처음부터 시작</button></div></div>');$('#restart-cancel').onclick=closeModal;$('#restart-confirm').onclick=async()=>{const b=$('#restart-confirm');b.disabled=true;try{const r=await request('restart',{});game=r.game;closeModal();render()}catch(e){b.disabled=false;showError(e,overlayContent)}}}
function rouletteText(prize,delta){if(prize.type==='views')return `조회수 +${fmt(prize.value)}`;if(prize.type==='penalty')return `오탈자 발견 · 신뢰도 하락 −${fmt(Math.abs(delta))}`;return `다음 ${game.state.published.length>=6?'보스전 그래프':'기사 발행'} 조회수 ${prize.value}배`}
function compactViews(value){return value>=10000?`${value/10000}만`:value>=1000?`${value/1000}천`:`${value}`}
function rouletteWheelText(prize){if(prize.type==='views')return `+${compactViews(prize.value)}`;if(prize.type==='penalty')return `오탈자<br>−${compactViews(prize.value)}`;return `다음<br>${prize.value}배`}
function rouletteResultModal(reward){const prize=reward.prize,delta=reward.views_delta||0,levelUp=reward.level_to>reward.level_from,title=prize.type==='views'?'🎉 조회수 보너스!':prize.type==='penalty'?'📝 오탈자 발견!':'🎁 배수 보관!';if(levelUp)flash();modal(`<div class="roulette-result"><span class="pill">룰렛 결과</span><h2>${title}</h2><div class="roulette-prize ${delta<0?'is-loss':''}">${delta>0?'+':''}${delta?fmt(delta)+' 👀':`×${prize.value}`}</div><p>${esc(rouletteText(prize,delta))}</p>${prize.type==='penalty'?'<div class="roulette-note">작은 오탈자가 발견돼 독자 신뢰가 흔들렸어요.</div>':''}${prize.type==='multiplier'?`<div class="roulette-note">${esc(reward.multiplier_target)}에 ${prize.value}배가 적용돼요.</div>`:''}${reward.postcards_unlocked?`<div class="new-postcards">📬 독자 엽서 ${reward.postcards_unlocked}장도 도착했어요!</div>`:''}${levelUp?`<div class="growth-celebration-inline">🎉 신문사가 성장했습니다! LEVEL ${reward.level_to===5?'MAX':reward.level_to} · ${esc(levelName(reward.level_to))}</div>`:''}<button class="btn primary full" id="roulette-result-ok">${reward.postcards_unlocked?'새 엽서 확인하기':'확인'}</button></div>`);$('#roulette-result-ok').onclick=()=>{closeModal();render();if(reward.postcards_unlocked){openReaderInbox();return}if(delta)animateViews(game.state.views-delta,game.state.views);if(levelUp){flash();$('.office',screen)?.classList.add('evolve')}}}
function spinRoulette(){if(!game?.state.roulette_pending||!overlay.classList.contains('hidden'))return;const prizes=game.content.settings.roulette||[],colors=['#54d9ff','#5277e8','#a971ef','#ffb344','#ee5e7a','#45c7a5','#d6a8ff','#ff704f'],step=360/prizes.length,gradient=prizes.map((_,i)=>`${colors[i%colors.length]} ${i*step}deg ${(i+1)*step}deg`).join(','),labels=prizes.map((p,i)=>`<span class="wheel-label" style="--angle:${i*step+step/2}deg">${rouletteWheelText(p)}</span>`).join('');modal(`<div class="roulette-modal"><span class="pill">📰 기사 발행 보너스</span><h2>룰렛을 돌려 보세요!</h2><p>조회수가 오르거나 다음 기사 배수가 생길 수 있어요.<br>오탈자가 발견되면 독자 신뢰도가 떨어질 수 있습니다.</p><div class="wheel-wrap"><div class="wheel-pointer" aria-hidden="true"></div><div class="wheel" id="publish-wheel" style="background:conic-gradient(${gradient})">${labels}</div></div><button class="btn primary full" id="spin-go">🎡 룰렛 돌리기</button></div>`);$('#spin-go').onclick=async()=>{const button=$('#spin-go');button.disabled=true;try{const result=await request('spin');game=result.game;const index=result.reward.prize_index,angle=1800-(index*step+step/2),wheel=$('#publish-wheel');wheel.style.transform=`rotate(${angle}deg)`;tone(600,.4,'triangle');setTimeout(()=>rouletteResultModal(result.reward),5200)}catch(e){button.disabled=false;showError(e,overlayContent)}}}
async function publish(){try{const r=await request('publish');game=r.game;rewardModal(r.reward,r.reward.article_count>1?`📰 ${r.reward.article_count}개 기사 한꺼번에 발행!`:'📰 기사 발행 성공!')}catch(e){showError(e)}}
function renderRecord(){const s=game.state,history=game.history||[];const rows=Object.entries(s.attempts).map(([key,a])=>`<tr><td>${esc(key.replace('article:','기사 ').replace('quiz:','퀴즈 ').replace('boss:','보스 '))}</td><td>${a.count}</td><td>${a.first_correct?'⭕':'❌'}</td><td>${a.wrong}</td></tr>`).join('');modal(`<h2>📋 나의 기록</h2><p>학습 점수 <b>${s.score}/100</b> · 총 시도 ${Object.values(s.attempts).reduce((a,x)=>a+x.count,0)}회</p><p>조회수 <b>${fmt(s.views)}</b> · 기사 ${s.article}/6</p><div class="table-wrap"><table><thead><tr><th>문제</th><th>시도</th><th>첫 시도</th><th>오답</th></tr></thead><tbody>${rows}</tbody></table></div>${history.length?`<h3>이전 판 기록</h3>${history.slice(-5).reverse().map(x=>`<p class="tiny">${x.run}판 · 조회수 ${fmt(x.views)} · 학습 점수 ${x.score}/100 · ${x.completed===false?'중간 재시작':'완료'} · ${esc(String(x.completed_at).slice(0,10))}</p>`).join('')}`:''}<p class="tiny">학습 점수는 각 문제의 첫 시도만 반영합니다.</p><button class="btn primary" onclick="closeModal()">닫기</button>`)}
function renderResult(){const s=game.state;screen.innerHTML=`<section class="panel hero"><span class="pill">🏆 전설의 편집장</span><h1>축하합니다!<br>${esc(game.profile.nickname)} 편집장</h1><p>오늘신문 특집 프로젝트 · 독자 질문 해결 ${s.solved.filter(k=>k.startsWith('quiz:')).length}/${game.content.quizzes.length} · 최종 팩트체크 4/4</p><div class="big-number">${fmt(s.views)} 👀</div><p>정확한 기사 제작과 독자 응답, 최종 검증까지 완료해 오늘신문을 지켜냈어요!</p><div class="stats"><div class="stat-card"><small>신문사</small><b>LEVEL ${game.level===5?'MAX':game.level}</b></div><div class="stat-card"><small>학습 점수</small><b>${s.score}/100</b></div><div class="stat-card"><small>총 시도</small><b>${Object.values(s.attempts).reduce((a,x)=>a+x.count,0)}회</b></div><div class="stat-card"><small>완료 기사</small><b>6개</b></div></div><h2 style="margin-top:20px">나의 최종 신문사</h2>${office(game.level)}<div class="row" style="margin-top:16px"><button class="btn primary" id="save-image">📷 결과 이미지 저장</button><button class="btn blue" id="record">📋 기록 보기</button></div>${game.finals.length?`<h2 style="margin-top:25px">🏁 동점자 결승</h2>${game.finals.map(f=>`<button class="btn full" data-final-play="${f.id}" ${f.complete?'disabled':''}>결승 문제 #${f.id} ${f.complete?'✅ 완료':f.attempts?'다시 도전':'풀기'}</button>`).join('')}`:''}</section>`;$('#save-image').onclick=downloadResult;$('#record').onclick=renderRecord;const restart=document.createElement('button');restart.className='btn pink';restart.textContent='🔄 새 판 시작';screen.querySelector('.row')?.append(restart);restart.onclick=confirmRestart;screen.querySelectorAll('[data-final-play]').forEach(b=>b.onclick=()=>renderFinalQuestion(+b.dataset.finalPlay))}
function renderFinalQuestion(id){const entry=game.finals.find(f=>f.id===id);if(!entry||entry.complete)return renderResult();const q=entry.question;screen.innerHTML=`<section class="panel"><span class="pill">🏁 동점자 결승 #${id}</span><h2>${esc(q.prompt)}</h2><p>첫 시도 정답만 결승 순위에 반영됩니다. 원래 학습 점수에는 합산되지 않습니다.</p>${q.choices.map((x,i)=>`<button class="choice" data-final-choice="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(x)}</button>`).join('')}<button class="btn blue" id="final-back">결과로 돌아가기</button></section>`;$('#final-back').onclick=renderResult;screen.querySelectorAll('[data-final-choice]').forEach(b=>b.onclick=async()=>{screen.querySelectorAll('[data-final-choice]').forEach(x=>x.disabled=true);try{const r=await request('final/answer',{final_id:id,choice:+b.dataset.finalChoice});game=r.game;modal(`<h2>${r.correct?'⭕ 결승 정답!':'❌ 다시 도전하세요'}</h2><p>${esc(r.explanation)}</p><p>${r.first_correct?'첫 시도 정답으로 기록됐습니다.':'결승 최초 정답 기록은 변경되지 않습니다.'}</p><button class="btn primary" id="final-ok">확인</button>`);$('#final-ok').onclick=()=>{closeModal();r.correct?renderResult():renderFinalQuestion(id)}}catch(e){showError(e)}})}
function downloadResult(){const s=game.state,canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const x=canvas.getContext('2d');x.fillStyle='#fff3d8';x.fillRect(0,0,1080,1350);x.fillStyle='#42466b';x.fillRect(38,38,1004,1274);x.fillStyle='#fffaf0';x.fillRect(48,48,984,1254);x.textAlign='center';x.fillStyle='#34395f';x.font='bold 70px sans-serif';x.fillText('📰 복합양식 편집부',540,160);x.font='bold 60px sans-serif';x.fillText('전설의 편집장 탄생!',540,270);x.font='50px sans-serif';x.fillText(game.profile.nickname+'의 신문사',540,350);x.fillStyle=['#d3b391','#e7b4ab','#a2c5df','#a9b5d0','#eed082'][game.level-1];x.fillRect(120,410,840,465);x.fillStyle='#f6fbff';x.fillRect(160,455,200,180);x.fillStyle='#7bc2e4';x.fillRect(177,472,166,145);x.fillStyle='#4b6080';x.fillRect(420,530,420,200);x.fillStyle='#b9845f';x.fillRect(230,715,620,90);x.font='110px sans-serif';x.fillText(game.level===5?'🏆 🎥 👩🏽‍💼':'🧑🏻‍💻 🖥️ 🪴',540,680);x.fillStyle='#34395f';x.font='bold 66px sans-serif';x.fillText('조회수 '+fmt(s.views),540,980);x.font='45px sans-serif';x.fillText('LEVEL '+(game.level===5?'MAX':game.level)+' · '+levelName(game.level),540,1050);x.fillText('학습 점수 '+s.score+'/100 · 기사 6/6',540,1130);x.font='31px sans-serif';x.fillText('정확한 자료로 세상을 바꾼 편집장',540,1210);const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='나의-신문사-결과.png';a.click()}
function renderAdminLogin(){game=null;screen.innerHTML=`<section class="panel"><h1>🔐 교사용 관리자</h1><p>서버에 설정한 교사 암호로 로그인하세요.</p><label class="field">암호<input type="password" id="admin-password" autocomplete="current-password"></label><button class="btn primary" id="admin-login">로그인</button><button class="btn" id="back">학생 화면</button></section>`;$('#back').onclick=renderWelcome;$('#admin-login').onclick=async()=>{try{await api('admin/login',{password:$('#admin-password').value});await loadAdmin()}catch(e){showError(e)}}}
async function loadAdmin(){try{adminData=await api('admin/state');renderAdmin()}catch(e){renderAdminLogin();showError(e)}}
function adminTabs(){const tabs=window.staticApi?[['content','📝 문제 편집'],['settings','⚙️ 보상 설정']]:[['dashboard','📊 현황·시상'],['content','📝 문제 편집'],['settings','⚙️ 게임 설정'],['final','🏁 결승']];return `<div class="tabs">${tabs.map(([id,label])=>`<button class="btn ${adminTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`}
function renderAdmin(){screen.innerHTML=`<section class="panel"><div class="row"><h1>교사용 편집실</h1><button class="btn" id="admin-logout">학생 화면으로</button></div><p class="notice">문제를 고친 뒤 <b>배포용 seed.json 다운로드</b>를 눌러 파일을 받아 주세요. 수정 파일을 이 채팅에 올리면 공개 사이트에 반영해 드립니다.</p>${adminTabs()}<div id="admin-body"></div></section>`;screen.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.tab;renderAdmin()});$('#admin-logout').onclick=async()=>{await api('logout',{});adminData=null;renderWelcome()};if(adminTab==='dashboard')renderDashboard();if(adminTab==='content')renderEditor();if(adminTab==='settings')renderSettings();if(adminTab==='final')renderFinal()}
function rankings(){const rows=adminData.students;const star=[...rows].sort((a,b)=>Number(b.completed)-Number(a.completed)||b.views-a.views||b.score-a.score);const analysis=[...rows].sort((a,b)=>b.score-a.score||a.attempts-b.attempts);return {star,analysis}}
function renderDashboard(){const rows=adminData.students,{star,analysis}=rankings();let body=$('#admin-body');body.innerHTML=`<h2>학생 진행 현황</h2><p>${rows.length}명 등록 · ${rows.filter(x=>x.completed).length}명 완료</p><div class="row"><button class="btn blue" id="export">⬇️ CSV 다운로드</button><button class="btn" id="refresh">새로고침</button></div><div class="row"><label class="field">반 필터<select id="class-filter"><option value="">전체</option>${adminData.content.classes.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field">정렬<select id="sort"><option value="class">반·번호</option><option value="score">학습 점수</option><option value="attempts">시도 횟수</option><option value="views">조회수</option><option value="completed">완료 여부</option></select></label></div><div class="table-wrap"><table><thead><tr><th>반</th><th>번호</th><th>닉네임</th><th>기사</th><th>점수</th><th>시도</th><th>조회수</th><th>레벨</th><th>완료</th></tr></thead><tbody id="student-rows"></tbody></table></div><h2>시상 후보</h2><p>⭐ 스타 편집장상: ${star[0]?`${esc(star[0].nickname)} (${fmt(star[0].views)}회)`: '아직 없음'}<br>🔍 최고의 분석 편집장상: ${analysis[0]?`${esc(analysis[0].nickname)} (${analysis[0].score}점)`: '아직 없음'}</p><p class="tiny muted">스타상은 완료 여부 → 조회수 → 학습 점수 순입니다. 분석상은 점수 → 총 시도 순입니다. 동점은 공동 후보이며 결승 문제로 결정할 수 있습니다.</p><label class="field">최종 수상자 지정<select id="award-kind"><option value="star">스타 편집장상</option><option value="analysis">최고의 분석 편집장상</option></select></label><select class="edit" id="award-student"><option value="">공동 수상/미지정</option>${rows.map(x=>`<option value="${x.id}">${esc(x.class_name)} ${x.student_no}번 ${esc(x.nickname)}</option>`).join('')}</select><button class="btn primary" id="award-save">시상 확정</button><h2 style="margin-top:22px">문항 분석</h2><div id="analytics"></div>`;
 function drawRows(){let list=[...rows],filter=$('#class-filter').value,sort=$('#sort').value;if(filter)list=list.filter(x=>x.class_name===filter);if(sort==='score')list.sort((a,b)=>b.score-a.score);if(sort==='attempts')list.sort((a,b)=>a.attempts-b.attempts);if(sort==='views')list.sort((a,b)=>b.views-a.views);if(sort==='completed')list.sort((a,b)=>Number(b.completed)-Number(a.completed));$('#student-rows').innerHTML=list.map(x=>`<tr><td>${esc(x.class_name)}</td><td>${x.student_no}</td><td>${esc(x.nickname)}</td><td>${x.article}/6</td><td>${x.score}</td><td>${x.attempts}</td><td>${fmt(x.views)}</td><td>${x.level}</td><td>${x.completed?'⭕':'-'}</td></tr>`).join('')};$('#class-filter').onchange=drawRows;$('#sort').onchange=drawRows;drawRows();
 const stats={};rows.forEach(x=>Object.entries(x.questions).forEach(([key,a])=>{const v=stats[key] ||= {n:0,correct:0,tries:0,choices:[0,0,0,0]};v.n++;v.correct+=a.first_correct?1:0;v.tries+=a.count;a.choices.forEach(c=>v.choices[c]++)}));$('#analytics').innerHTML=`<div class="table-wrap"><table><tr><th>문제</th><th>첫 시도 정답률</th><th>평균 시도</th><th>선택 비율 A/B/C/D</th></tr>${Object.entries(stats).sort((a,b)=>a[1].correct/a[1].n-b[1].correct/b[1].n).map(([key,v])=>`<tr><td>${esc(key)}</td><td>${Math.round(v.correct/v.n*100)}%</td><td>${(v.tries/v.n).toFixed(1)}</td><td>${v.choices.map(n=>Math.round(n/v.tries*100)+'%').join(' / ')}</td></tr>`).join('')}</table></div>`;
 $('#export').onclick=()=>{location.href='/api/admin/export'+($('#class-filter').value?'?class='+encodeURIComponent($('#class-filter').value):'')};$('#refresh').onclick=loadAdmin;$('#award-save').onclick=async()=>{try{await api('admin/award',{kind:$('#award-kind').value,student_id:$('#award-student').value?+$('#award-student').value:null});await loadAdmin();modal('<h2>시상 기록을 저장했습니다.</h2><button class="btn primary" onclick="closeModal()">확인</button>')}catch(e){showError(e)}};
}
function editField(label,value,path,type='text'){const tag=type==='textarea'?`<textarea data-path="${esc(path)}" class="edit">${esc(value)}</textarea>`:`<input data-path="${esc(path)}" class="edit" type="${type}" value="${esc(value)}">`;return `<label class="field">${esc(label)}${tag}</label>`}
function questionEditor(q,prefix,media=false){const multi=q.type==='multi';return `<div class="admin-form">${editField('질문',q.prompt,prefix+'.prompt')}${multi?'<p class="tiny">복수 정답 문제: 정답인 선택지를 모두 체크하세요.</p>':''}${q.choices.map((c,i)=>{const value=media?c.title:c,checked=multi?(q.answer||[]).includes(i):q.answer===i;return `<div class="choice-edit"><div class="inline"><input type="${multi?'checkbox':'radio'}" name="answer-${prefix}" data-answer="${prefix}" value="${i}" ${checked?'checked':''}><b>선택지 ${q.type==='ox'?esc(c):'ABCD'[i]} · 정답</b></div>${editField('내용',value,prefix+'.choices.'+i+(media?'.title':''))}${media?`${editField('자료 종류',c.kind,prefix+'.choices.'+i+'.kind')}${editField('출처',c.source,prefix+'.choices.'+i+'.source')}${editField('조사 시기',c.period,prefix+'.choices.'+i+'.period')}${editField('단위',c.unit,prefix+'.choices.'+i+'.unit')}${editField('이미지 URL 또는 data URL',c.image,prefix+'.choices.'+i+'.image')}<label class="field tiny">이미지 업로드<input type="file" accept="image/*" data-upload="${prefix}.choices.${i}.image"></label>`:''}</div>`}).join('')}${editField('힌트',q.hint||'',prefix+'.hint')}${editField('해설',q.explanation,prefix+'.explanation','textarea')}${q.image!==undefined?`${editField('문제 이미지 URL',q.image,prefix+'.image')}<label class="field tiny">문제 이미지 업로드<input type="file" accept="image/*" data-upload="${prefix}.image"></label>`:''}</div>`}
function bindEditorUploads(){screen.querySelectorAll('[data-upload]').forEach(input=>input.onchange=()=>{const f=input.files[0];if(!f)return;if(f.size>300000) return showError(Error('이미지는 300KB 이하로 줄여 주세요.'));const reader=new FileReader();reader.onload=()=>{const target=screen.querySelector(`[data-path="${input.dataset.upload}"]`);target.value=reader.result};reader.readAsDataURL(f)})}
function setPath(root,path,value){const bits=path.split('.');let cur=root;for(const bit of bits.slice(0,-1))cur=cur[bit];cur[bits[bits.length-1]]=value}
function collectEditor(){const c=copyAppData(adminData.content);screen.querySelectorAll('[data-path]').forEach(el=>setPath(c,el.dataset.path,el.type==='number'?Number(el.value):el.value));const multiAnswers=new Map();screen.querySelectorAll('[data-answer]:checked').forEach(el=>{const path=el.dataset.answer+'.answer';if(el.type==='checkbox'){if(!multiAnswers.has(path))multiAnswers.set(path,[]);multiAnswers.get(path).push(Number(el.value))}else setPath(c,path,Number(el.value))});for(const [path,answer] of multiAnswers)setPath(c,path,answer);return c}
async function saveContent(){try{const content=collectEditor(),r=await api('admin/content',{content});content.version=r.version;adminData.content=content;adminData.version=r.version;modal(`<h2>✅ 수정본을 준비했어요</h2><p>아래 파일을 내려받아 이 채팅에 올려 주세요. 제가 학생들이 보는 사이트에 적용할게요.</p><button class="btn primary full" id="download-seed">📥 seed.json 다운로드</button><button class="btn" style="margin-top:8px" id="close-save">닫기</button>`);$('#download-seed').onclick=()=>downloadSeed(content);$('#close-save').onclick=closeModal}catch(e){showError(e)}}
function downloadSeed(content=collectEditor()){const blob=new Blob([JSON.stringify(content,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='seed.json';a.click();URL.revokeObjectURL(url)}
function renderEditor(){const c=adminData.content;let html=`<h2>문제 편집 · 버전 ${adminData.version}</h2><p class="tiny">기사를 고친 뒤 저장하고, 내려받은 seed.json을 이 채팅에 올리면 제가 공개 사이트에 반영합니다.</p><div class="section-nav">${[['article','기사 6개'],['quiz',`독자 엽서 질문 ${c.quizzes.length}개`],['boss','보스 3단계']].map(([id,label])=>`<button class="btn ${editTab===id?'active':''}" data-edit-tab="${id}">${label}</button>`).join('')}</div><div class="section-nav" style="margin-top:10px">${Array.from({length:editTab==='article'?6:editTab==='quiz'?c.quizzes.length:3},(_,i)=>`<button class="btn ${editIndex===i?'active':''}" data-index="${i}">${i+1}</button>`).join('')}</div>`;
 if(editTab==='article'){const a=c.articles[editIndex],p=`articles.${editIndex}`;html+=`<div class="admin-form"><h2>기사 ${editIndex+1}</h2>${editField('기사 제목',a.title,p+'.title')}${editField('기사 원고',a.body,p+'.body','textarea')}<h3>자료 선택 문제</h3>${questionEditor(a.select,p+'.select',true)}<h3>자료 효과 문제</h3>${questionEditor(a.effect,p+'.effect')}</div><div class="row"><button class="btn" id="duplicate">현재 기사를 다음 칸으로 복제</button><button class="btn" id="move-up">순서 ↑</button><button class="btn" id="move-down">순서 ↓</button></div>`}
 if(editTab==='quiz'){const q=c.quizzes[editIndex];html+=`<h2>독자 엽서 ${editIndex+1}</h2>${questionEditor(q,`quizzes.${editIndex}`)}`}
 if(editTab==='boss')html+=`<h2>보스전 ${editIndex+1}단계</h2>${questionEditor(c.boss[editIndex],`boss.${editIndex}`)}`;
 html+=`<button class="btn primary full" id="save-content" style="margin-top:16px">💾 수정 저장하고 파일 받기</button><div class="row" style="margin-top:13px"><button class="btn blue" id="preview">👀 학생 화면 미리보기</button><button class="btn" id="backup">⬇️ seed.json 다시 받기</button><label class="btn">⬆️ 기존 문제 파일 불러오기<input id="restore" type="file" accept="application/json" hidden></label></div>`;$('#admin-body').innerHTML=html;
 screen.querySelectorAll('[data-edit-tab]').forEach(b=>b.onclick=()=>{editTab=b.dataset.editTab;editIndex=0;renderEditor()});screen.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{editIndex=+b.dataset.index;renderEditor()});bindEditorUploads();$('#save-content').onclick=saveContent;
 $('#preview').onclick=()=>{const q=editTab==='article'?c.articles[editIndex].select:editTab==='quiz'?c.quizzes[editIndex]:c.boss[editIndex];modal(`<h2>${esc(q.prompt)}</h2>${q.choices.map((x,i)=>`<p class="choice">${'ABCD'[i]}. ${esc(typeof x==='string'?x:x.title)}</p>`).join('')}<button class="btn primary" onclick="closeModal()">닫기</button>`)};
 $('#backup').onclick=()=>downloadSeed(collectEditor());
 $('#restore').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.articles)||data.articles.length!==6)throw Error('올바른 문제 백업 파일이 아닙니다.');adminData.content=data;renderEditor()}catch(err){showError(err)}};
 if(editTab==='article'){const change=(mode)=>{const items=collectEditor().articles;if(mode==='duplicate'&&editIndex<5)items[editIndex+1]=copyAppData(items[editIndex]);if(mode==='up'&&editIndex>0){[items[editIndex-1],items[editIndex]]=[items[editIndex],items[editIndex-1]];editIndex--}if(mode==='down'&&editIndex<5){[items[editIndex+1],items[editIndex]]=[items[editIndex],items[editIndex+1]];editIndex++}adminData.content.articles=items;renderEditor()};$('#duplicate').onclick=()=>change('duplicate');$('#move-up').onclick=()=>change('up');$('#move-down').onclick=()=>change('down')}
}
function rouletteSettingName(prize){if(prize.type==='views')return `조회수 +${fmt(prize.value)}`;if(prize.type==='penalty')return `오탈자 신뢰도 하락 −${fmt(prize.value)}`;return `다음 배수 ×${prize.value}`}
function renderSettings(){const s=adminData.content.settings;$('#admin-body').innerHTML=`<h2>게임 설정</h2><p class="tiny">확률 합계는 각각 100이어야 합니다. 기존 학생의 진행과 채점은 해당 학생이 시작한 문제 버전으로 유지됩니다.</p>${editField('반 목록 (쉼표로 구분)',adminData.content.classes.join(', '),'classes_text')}${editField('기본 기사 조회수',s.base_views,'settings.base_views','number')}<label class="field">게임 시작/종료<select class="edit" data-path="settings.open"><option value="true" ${s.open?'selected':''}>시작 허용</option><option value="false" ${!s.open?'selected':''}>새 등록 닫기</option></select></label><label class="field">효과음 기본 설정<select class="edit" data-path="settings.sound"><option value="true" ${s.sound?'selected':''}>켜기</option><option value="false" ${!s.sound?'selected':''}>끄기</option></select></label><h3>사무실 성장 조회수</h3>${s.thresholds.slice(1).map((x,i)=>editField('LEVEL '+(i===3?'MAX':i+2),x,`settings.thresholds.${i+1}`,'number')).join('')}<h3>기사 랜덤 배수</h3>${s.multipliers.map((x,i)=>editField(x.value+'배 확률 (%)',x.weight,`settings.multipliers.${i}.weight`,'number')).join('')}<h3>기사 발행 룰렛</h3>${(s.roulette||[]).map((x,i)=>`<div class="admin-form">${editField(rouletteSettingName(x),x.value,`settings.roulette.${i}.value`,'number')}${editField('확률 (%)',x.weight,`settings.roulette.${i}.weight`,'number')}</div>`).join('')}<button class="btn primary full" id="save-settings">💾 설정 저장</button>`;
 $('#save-settings').onclick=async()=>{try{const c=copyAppData(adminData.content);screen.querySelectorAll('[data-path]').forEach(el=>{if(el.dataset.path==='classes_text')c.classes=el.value.split(',').map(x=>x.trim()).filter(Boolean);else setPath(c,el.dataset.path,el.type==='number'?Number(el.value):el.value==='true'?true:el.value==='false'?false:el.value)});const wheelWeightTotal=(c.settings.roulette||[]).reduce((sum,x)=>sum+Number(x.weight||0),0);if(wheelWeightTotal!==100)throw Error('기사 발행 룰렛 확률의 합계가 100%가 되도록 맞춰 주세요.');const r=await api('admin/content',{content:c});c.version=r.version;adminData.content=c;adminData.version=r.version;modal('<h2>✅ 설정이 저장됐습니다.</h2><p>배포용 파일도 함께 내려받아 이 채팅에 올려 주세요.</p><button class="btn primary full" id="download-settings">seed.json 다운로드</button><button class="btn" id="close-settings">닫기</button>');$('#download-settings').onclick=()=>downloadSeed(c);$('#close-settings').onclick=closeModal}catch(e){showError(e)}}
}
function renderFinal(){const {analysis}=rankings(),best=analysis[0],ties=best?analysis.filter(x=>x.score===best.score&&x.attempts===best.attempts):[];$('#admin-body').innerHTML=`<h2>동점자 결승</h2><p>학습 점수 1위가 여러 명이면 추가 문제를 만들고 해당 학생들에게만 참여 권한을 줄 수 있습니다. 결승 점수는 원래 100점에 합산하지 않습니다.</p><p>현재 공동 1위 후보: ${ties.map(x=>esc(x.nickname)).join(', ')||'없음'}</p><div class="admin-form"><h3>새 결승 문제</h3><label class="field">질문<input class="edit" id="final-prompt" placeholder="자료의 적합성·신뢰성·효과를 판단하는 문제"></label>${[0,1,2,3].map(i=>`<label class="field">선택지 ${'ABCD'[i]}<input class="edit" id="final-${i}"></label>`).join('')}<label class="field">정답<select class="edit" id="final-answer">${[0,1,2,3].map(i=>`<option value="${i}">${'ABCD'[i]}</option>`).join('')}</select></label><label class="field">해설<textarea class="edit" id="final-explanation"></textarea></label><button class="btn primary" id="final-create">결승 문제 저장·공동 1위에게 배정</button></div><h3>저장된 결승 문제</h3>${adminData.finals.map(f=>`<div class="mission-card">#${f.id} · ${esc(JSON.parse(f.body).prompt)}<br><button class="btn" data-final="${f.id}">현재 공동 1위에게 추가 배정</button></div>`).join('')||'<p>아직 없습니다.</p>'}<p class="tiny muted">결승 문제를 추가로 내거나 공동 수상을 선택할 수 있습니다.</p>`;
 $('#final-create').onclick=async()=>{try{if(ties.length<2)throw Error('공동 1위가 최소 2명 필요합니다.');const question={prompt:$('#final-prompt').value,choices:[0,1,2,3].map(i=>$('#final-'+i).value),answer:+$('#final-answer').value,explanation:$('#final-explanation').value,hint:''};await api('admin/final',{question,student_ids:ties.map(x=>x.id)});await loadAdmin()}catch(e){showError(e)}};screen.querySelectorAll('[data-final]').forEach(b=>b.onclick=async()=>{try{await api('admin/final/assign',{final_id:+b.dataset.final,student_ids:ties.map(x=>x.id)});modal('<h2>결승 참여 권한을 배정했습니다.</h2><button class="btn primary" onclick="closeModal()">확인</button>')}catch(e){showError(e)}})
}
const originalRenderFinal=renderFinal;
renderFinal=function(){
 originalRenderFinal();
 const body=$('#admin-body');
 const status=document.createElement('p');status.className='notice';status.textContent='결승 현황: '+adminData.students.filter(x=>x.final_assigned).map(x=>`${x.nickname} ${x.final_first_correct}/${x.final_assigned}문항 첫 시도 정답`).join(' · ');
 body.append(status);
 body.querySelectorAll('[data-final]').forEach(button=>{
   const id=+button.dataset.final,card=button.closest('.mission-card');
   const edit=document.createElement('button');edit.className='btn';edit.textContent='수정';card.append(edit);
   const remove=document.createElement('button');remove.className='btn';remove.textContent='삭제';card.append(remove);
   edit.onclick=()=>{const q=JSON.parse(adminData.finals.find(x=>x.id===id).body);$('#final-prompt').value=q.prompt;q.choices.forEach((x,i)=>$('#final-'+i).value=x);$('#final-answer').value=q.answer;$('#final-explanation').value=q.explanation;const save=$('#final-create');save.textContent='결승 문제 수정 저장';save.onclick=async()=>{try{const question={prompt:$('#final-prompt').value,choices:[0,1,2,3].map(i=>$('#final-'+i).value),answer:+$('#final-answer').value,explanation:$('#final-explanation').value,hint:''};await api('admin/final/edit',{final_id:id,question});await loadAdmin()}catch(e){showError(e)}};$('#final-prompt').scrollIntoView({behavior:'smooth'})};
   remove.onclick=async()=>{if(!confirm('이 결승 문제를 삭제할까요?'))return;try{await api('admin/final/delete',{final_id:id});await loadAdmin()}catch(e){showError(e)}};
 });
};
const originalRenderEditor=renderEditor;
renderEditor=function(){
 originalRenderEditor();
 if(window.staticApi)return;
 if(editTab==='boss'){
   const dialogue=document.createElement('div');dialogue.innerHTML=editField('악덕 편집장 등장 대사',adminData.content.boss_dialogue||'조회수만 잘 나오면 되는 거 아니야?','boss_dialogue');
   $('#admin-body').querySelector('.admin-form')?.before(dialogue);
 }
 $('#preview').onclick=()=>{const content=collectEditor(),q=editTab==='article'?content.articles[editIndex].select:editTab==='quiz'?content.quizzes[editIndex]:content.boss[editIndex];modal(`<h2>${esc(q.prompt)}</h2>${q.choices.map((x,i)=>`<p class="choice">${'ABCD'[i]}. ${esc(typeof x==='string'?x:x.title)}</p>`).join('')}<button class="btn primary" onclick="closeModal()">닫기</button>`)};
 const box=document.createElement('div');box.className='admin-form';
 box.innerHTML=`<h3>변경 내역</h3><p class="tiny">이전 버전을 복원하면 새로운 버전으로 저장됩니다. 기존 학생의 점수는 유지됩니다.</p><select class="edit" id="version-choice">${(adminData.versions||[]).map(v=>`<option value="${v.id}">버전 ${v.id} · ${esc(v.created)}</option>`).join('')}</select><button class="btn" id="version-restore">선택한 버전 복원</button>`;
 $('#admin-body').append(box);
 $('#version-restore').onclick=async()=>{if(!confirm('선택한 문제 버전을 현재 버전으로 복원할까요?'))return;try{await api('admin/version/restore',{version:+$('#version-choice').value});await loadAdmin()}catch(e){showError(e)}};
};
const originalRenderDashboard=renderDashboard;
renderDashboard=function(){
 originalRenderDashboard();
 const rows=adminData.students,box=document.createElement('div');box.className='admin-form';
 box.innerHTML=`<h3>반별 평균 점수</h3><div class="table-wrap"><table><tr><th>반</th><th>학생 수</th><th>평균 학습 점수</th></tr>${adminData.content.classes.map(c=>{const group=rows.filter(x=>x.class_name===c);return `<tr><td>${esc(c)}</td><td>${group.length}</td><td>${group.length?(group.reduce((n,x)=>n+x.score,0)/group.length).toFixed(1):'-'}</td></tr>`}).join('')}</table></div>`;
 $('#admin-body').append(box);
};
const originalRenderSettings=renderSettings;
renderSettings=function(){
 originalRenderSettings();
 if(!window.staticApi)return;
 const imageBox=document.createElement('div');imageBox.className='admin-form';imageBox.innerHTML='<h3>레벨별 사무실 이미지</h3><p class="tiny">각 단계에 쓸 이미지를 골라 주세요. 이미지가 포함된 seed.json 파일을 내려받게 됩니다.</p>'+Array.from({length:5},(_,i)=>`<label class="field">LEVEL ${i===4?'MAX':i+1} 이미지<input class="edit" type="file" accept="image/*" data-office-image="${i}"></label><div class="tiny muted" data-office-name="${i}">${adminData.content.settings.office_images?.[i]?'이미지 등록됨':'아직 이미지 없음'}</div>`).join('');$('#admin-body').prepend(imageBox);
 imageBox.querySelectorAll('[data-office-image]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const objectUrl=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const probe=new Image();probe.onload=()=>resolve(probe);probe.onerror=()=>reject(Error('이미지 파일을 열 수 없습니다.'));probe.src=objectUrl}),scale=Math.min(1,1280/image.width,720/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.78);adminData.content.settings.office_images ||= Array(5).fill('');adminData.content.settings.office_images[+input.dataset.officeImage]=data;imageBox.querySelector(`[data-office-name="${input.dataset.officeImage}"]`).textContent=`선택됨: ${file.name} (화면용으로 자동 조정)`}catch(e){showError(e)}finally{URL.revokeObjectURL(objectUrl)}});
 const button=document.createElement('button');button.className='btn primary full';button.style.marginTop='12px';button.textContent='💾 저장하고 배포용 seed.json 받기';
 button.onclick=()=>$('#save-settings').click();$('#admin-body').append(button);
};
const originalRenderWelcome=renderWelcome;
renderWelcome=function(){
 originalRenderWelcome();
 screen.insertAdjacentHTML('beforeend',teacherEditLink());
};
async function boot(){try{const d=await api('bootstrap');classes=d.classes;game=d.game;if(game&&localStorage.getItem('sound')===null){soundOn=!!game.content.settings.sound;$('#sound').textContent=soundOn?'🔊':'🔇'}if(d.admin)await loadAdmin();else render()}catch(e){screen.innerHTML='<section class="panel"><h2>서버 연결 실패</h2><p>잠시 후 새로고침해 주세요.</p></section>';showError(e)}}boot();
